    if(!alive(handle,NativeKind::Unit))return;auto state=units_.at(handle);if(state->removing)return;if(state->soulVictim)releaseSoul(handle);else if(state->soulCaptor)releaseSoul(state->soulCaptor);clearPlayerOrders(handle);state->removing=true;for(auto& slot:ais_)if(slot){slot->captain.erase(handle);slot->defenderUnits.erase(handle);slot->suicideUnits.erase(handle);slot->retreatOrders.erase(handle);if(slot->captainRoute)slot->captainRoute->members.erase(handle);}cancelSacrificeForUnit(handle);if(state->moonWellWaterEffect){destroyEffect(state->moonWellWaterEffect);effects_.erase(state->moonWellWaterEffect);state->moonWellWaterEffect=0;}clearConcoction(handle);clearWeaponEffects(*state);clearWarClub(*state);noteSpiritMember(*state);clearSpiritSplit(*state);clearLavaSpawn(*state);removeLocust(handle);releaseCorpseSummon(*state);killDependentSummons(handle);removePhoenixFire(handle);clearDeathRestart(*state);stasisWards_.erase(handle);rootActors_.erase(handle);unitFormActors_.erase(handle);corpseHandles_.erase(handle);++fogRevision_;releaseCargo(*state);cancelUnsummon(*state);cancelHeroRevival(handle);cancelBuildingRevivals(handle);clearAuras(*state);releaseAuraSource(handle);for(auto& [id,buff]:state->buffs)releaseBuff(buff);state->buffs.clear();cancelCombat(*state);unitFootprint(*state);auto held=state->inventory;auto jobs=std::move(state->production);state->production.clear();for(auto& job:jobs)releaseSacrifice(job,*state);int reserved=state->construction?state->construction->food:0;state->construction.reset();if(state->buildingUpgrade)reserved+=state->buildingUpgrade->food;state->buildingUpgrade.reset();for(auto& job:jobs)if(job.reserved)reserved+=job.food;auto tokenOwner=state->owner;auto tokenCount=std::count_if(jobs.begin(),jobs.end(),[](const auto& job){return job.heroToken;});int tokensBefore=0,tokensAfter=0;std::uint64_t tokenRevision=0;if(tokenCount){auto& tokenState=config_.players[tokenOwner].states[3];tokensBefore=tokenState;tokensAfter=tokenState=int(std::min(std::int64_t(INT_MAX),std::int64_t(tokenState)+tokenCount));tokenRevision=playerStateRevisions_[tokenOwner][3];}releaseBuilder(handle,false);unitFood(handle,false,reserved);releaseMine(*state);
