void ScriptSession::bindFoodNatives() {
    bind("SetUnitUseFood","nothing",{"unit","boolean"},[this](auto& vm,auto a){if(!alive(a[0].bits,NativeKind::Unit))return vm.nothing();auto& u=unit(a[0]);if(u.sacrificePit && u.useFood!=(a[1].bits!=0)){cancelSacrificeForUnit(a[0].bits);if(!alive(a[0].bits,NativeKind::Unit))return vm.nothing();}auto& current=unit(a[0]);current.useFood=a[1].bits!=0;unitFood(a[0].bits,current.useFood);return vm.nothing();});
    for(auto [name,capacity]:std::initializer_list<std::pair<const char*,bool>>{{"GetFoodUsed",false},{"GetFoodMade",true}})bind(name,"integer",{"integer"},[this,capacity](auto& vm,auto a){if(!definitions().contains(a[0].bits))return vm.integer(0);return vm.integer(int(definitions().number(a[0].bits,"UnitBalance",capacity?"fmade":"fused")));});

}
